<script setup lang="ts">
import { Plus, Trash2, Pencil, ArrowLeft } from 'lucide-vue-next'
import type { Trip, Expense } from '~/types/models'
const route = useRoute(), db = useDb(), record = ref<Trip | null>(null), expenses = ref<Expense[]>([]), busy = ref(true), error = ref(''), editing = ref(false), expenseEditor = ref(false), currentExpense = ref<Expense | null>(null)
const id = computed(() => String(route.params.id))
async function load() { error.value = ''; try { [record.value, expenses.value] = await Promise.all([db.trip(id.value), db.expenses(id.value)]) } catch(e) { error.value = message(e) } finally { busy.value = false } }
onMounted(load)
const total = computed(() => expensesTotal(expenses.value))
const profit = computed(() => routeProfit(record.value?.service_price || 0, expenses.value))
const outstanding = computed(() => pendingCollection(record.value ? [record.value] : [], expenses.value))
async function deleteExpense(e: Expense) { if (!confirm('¿Eliminar este gasto?')) return; try { await db.remove('expenses',e.id); await load() } catch (err) { error.value = message(err) } }
async function deleteTrip() { if (!confirm('¿Eliminar este viaje y todos sus gastos? Esta acción no se puede deshacer.')) return; try { await db.remove('trips',id.value); await navigateTo('/trips') } catch(e) { error.value = message(e) } }
</script>
<template><div v-if="busy" class="empty">Cargando detalle...</div><div v-else-if="error" class="alert danger">{{error}}</div><template v-else-if="record"><div class="page-heading"><div><NuxtLink to="/trips" class="backlink"><ArrowLeft :size="15"/> Volver a viajes</NuxtLink><h1>{{record.origin}} → {{record.destination}}</h1><p class="muted">{{record.platform?.name || 'Sin plataforma'}} · {{shortDate(record.start_at)}}</p></div><div class="heading-actions"><button class="button secondary" @click="editing = !editing"><Pencil :size="17"/> {{editing ? 'Cerrar edición' : 'Editar'}}</button><button class="button danger-button" @click="deleteTrip"><Trash2 :size="17"/> Eliminar</button></div></div>
<TripForm v-if="editing" :initial="record" @saved="async () => { editing = false; await load() }"/>
<template v-else><div class="stats-grid"><div class="stat card"><span class="muted">Precio servicio</span><strong>{{euro(record.service_price)}}</strong></div><div class="stat card"><span class="muted">Gastos registrados</span><strong>{{euro(total)}}</strong></div><div class="stat card"><span class="muted">Beneficio operativo</span><strong class="green">{{euro(profit)}}</strong></div><div class="stat card"><span class="muted">Pendiente de cobrar</span><strong>{{euro(outstanding)}}</strong></div></div>
<div class="card summary-grid"><div><span class="muted">Inicio</span><b>{{shortDate(record.start_at)}}</b></div><div><span class="muted">Fin</span><b>{{shortDate(record.end_at)}}</b></div><div><span class="muted">Kilómetros</span><b>{{record.kilometers ?? '—'}}</b></div><div><span class="muted">Presupuesto estimado</span><b>{{euro(record.estimated_budget)}}</b></div><div><span class="muted">Servicio cobrado</span><b>{{euro(record.service_collected)}}</b></div><div><span class="muted">Referencia</span><b>{{record.external_reference || '—'}}</b></div><div class="wide"><span class="muted">Observaciones</span><p>{{record.notes || 'Sin observaciones.'}}</p></div></div>
<div class="section-heading"><h2>Gastos asociados <span class="muted">({{expenses.length}})</span></h2><button class="button primary" @click="currentExpense = null; expenseEditor = true"><Plus :size="17"/> Añadir gasto</button></div>
<ExpenseForm v-if="expenseEditor" :key="currentExpense?.id || 'new'" :trip-id="id" :initial="currentExpense" @cancel="expenseEditor = false" @saved="async () => { expenseEditor = false; await load() }"/>
<div v-if="!expenses.length" class="card empty">No has registrado gastos para este viaje.</div><div v-else class="card table-wrap"><table><thead><tr><th>Fecha</th><th>Concepto</th><th>Tipo</th><th>Importe</th><th>Reembolsable</th><th>Reembolsado</th><th></th></tr></thead><tbody><tr v-for="e in expenses" :key="e.id"><td>{{shortDate(e.spent_at)}}</td><td>{{e.description || '—'}}</td><td>{{e.expense_type?.name || 'Otros'}}</td><td>{{euro(e.amount)}}</td><td>{{euro(e.refundable_amount)}}</td><td>{{euro(e.reimbursed_amount)}}</td><td><div class="action-row"><button title="Editar gasto" class="icon-button" @click="currentExpense = e; expenseEditor = true"><Pencil :size="17"/></button><button title="Eliminar gasto" class="icon-button" @click="deleteExpense(e)"><Trash2 :size="17"/></button></div></td></tr></tbody></table></div>
</template></template></template>
